config.renderFunction:
function render(ctx, width, height, state) {
  const A = Math.round(state.numA);
  const B = Math.round(state.numB);

  function getPrimeFactors(n) {
    const factors = [];
    let d = 2;
    let temp = n;
    while (temp >= 2) {
      if (temp % d === 0) {
        factors.push(d);
        temp /= d;
      } else {
        d++;
        if (d * d > temp) {
          if (temp > 1) factors.push(temp);
          break;
        }
      }
    }
    return factors;
  }

  function getCounts(arr) {
    const counts = {};
    arr.forEach(x => { counts[x] = (counts[x] || 0) + 1; });
    return counts;
  }

  const factorsA = getPrimeFactors(A);
  const factorsB = getPrimeFactors(B);
  const countA = getCounts(factorsA);
  const countB = getCounts(factorsB);

  const allPrimes = Array.from(new Set([...Object.keys(countA), ...Object.keys(countB)])).map(Number).sort((a,b)=>a-b);

  const shared = [];
  const onlyA = [];
  const onlyB = [];
  let gcf = 1;
  let lcm = 1;

  allPrimes.forEach(p => {
    const cA = countA[p] || 0;
    const cB = countB[p] || 0;
    const minP = Math.min(cA, cB);
    const maxP = Math.max(cA, cB);

    for(let i=0; i<minP; i++) { shared.push(p); gcf *= p; }
    for(let i=0; i<cA - minP; i++) onlyA.push(p);
    for(let i=0; i<cB - minP; i++) onlyB.push(p);
    lcm *= Math.pow(p, maxP);
  });

  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, 0, width, height);

  const r = 85;
  const cy = height / 2 - 10;
  const cxA = width / 2 - 55;
  const cxB = width / 2 + 55;

  ctx.beginPath();
  ctx.arc(cxA, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(59, 130, 246, 0.25)';
  ctx.fill();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = '#3b82f6';
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cxB, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(168, 85, 247, 0.25)';
  ctx.fill();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = '#a855f7';
  ctx.stroke();

  ctx.font = 'bold 15px sans-serif';
  ctx.fillStyle = '#60a5fa';
  ctx.textAlign = 'center';
  ctx.fillText('Set A: ' + A, cxA - 35, cy - r - 12);

  ctx.fillStyle = '#c084fc';
  ctx.fillText('Set B: ' + B, cxB + 35, cy - r - 12);

  ctx.font = '13px monospace';
  ctx.fillStyle = '#93c5fd';
  onlyA.forEach((val, idx) => {
    ctx.fillText('• ' + val, cxA - 42, cy - 25 + idx * 20);
  });

  ctx.fillStyle = '#d8b4fe';
  onlyB.forEach((val, idx) => {
    ctx.fillText('• ' + val, cxB + 42, cy - 25 + idx * 20);
  });

  ctx.fillStyle = '#34d399';
  ctx.font = 'bold 14px monospace';
  shared.forEach((val, idx) => {
    ctx.fillText('★ ' + val, width / 2, cy - 25 + idx * 20);
  });

  ctx.font = '13px sans-serif';
  ctx.fillStyle = '#e2e8f0';
  ctx.textAlign = 'center';
  ctx.fillText('GCF (Intersection) = ' + gcf + '   |   LCM (Union) = ' + lcm + '   |   A × B = ' + (A * B) + ' = GCF × LCM', width / 2, height - 20);
}
